questions.question_text:
$X$ is uniformly distributed on $[7,15]$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw[-{Stealth}] (-0.5,0) -- (6.2,0) node[right] {$x$};
\draw[white,line width=3pt] (0.35,0) -- (0.75,0);
\draw (0.35,-0.1) -- (0.55,0.1) (0.55,-0.1) -- (0.75,0.1);
\draw[-{Stealth}] (0,-0.4) -- (0,3.0) node[above] {$y$};
\draw[thick] (1,0) -- (1,2) -- (5,2) -- (5,0);
\node[below] at (1,0) {$7$};
\node[below] at (5,0) {$15$};
\end{tikzpicture}
[/tikz]
What is $f(x)$ on $[7,15]$?

$X$ is uniformly distributed on $[0,20]$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw[-{Stealth}] (-0.5,0) -- (6.2,0) node[right] {$x$};
\draw[-{Stealth}] (0,-0.4) -- (0,3.0) node[above] {$y$};
\draw[thick] (0,0) -- (0,2) -- (5,2) -- (5,0);
\node[below] at (0,0) {$0$};
\node[below] at (5,0) {$20$};
\node[left] at (0,2) {$\frac{1}{20}$};
\end{tikzpicture}
[/tikz]
Find $P(6\le X\le 11)$.

questions.solution_text:
$P(6\le X\le 11)=\frac{11-6}{20-0}$
$=\frac{5}{20}$
$=\frac{1}{4}$
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\fill[gray!35] (1.5,0) rectangle (2.75,2);
\draw[-{Stealth}] (-0.5,0) -- (6.2,0) node[right] {$x$};
\draw[-{Stealth}] (0,-0.4) -- (0,3.0) node[above] {$y$};
\draw[thick] (0,0) -- (0,2) -- (5,2) -- (5,0);
\node[below] at (0,0) {$0$};
\node[below] at (1.5,0) {$6$};
\node[below] at (2.75,0) {$11$};
\node[below] at (5,0) {$20$};
\node[left] at (0,2) {$\frac{1}{20}$};
\end{tikzpicture}
[/tikz]

questions.question_text:
$X$ is uniformly distributed on $[3,13]$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw[-{Stealth}] (-0.5,0) -- (6.2,0) node[right] {$x$};
\draw[white,line width=3pt] (0.35,0) -- (0.75,0);
