\draw[-{Stealth}] (0,-0.4) -- (0,3.0) node[above] {$y$};
\draw[thick] (1,0) -- (1,2) -- (5,2) -- (5,0);
\draw[dashed] (0,2) -- (1,2);
\node[below] at (1,0) {$3$};
\node[below] at (5,0) {$13$};
\node[left] at (0,2) {$\frac{1}{10}$};
\end{tikzpicture}
[/tikz]
Find $P(X>9)$.

questions.solution_text:
$P(X>9)=\frac{13-9}{13-3}$
$=\frac{4}{10}$
$=\frac{2}{5}$
